(function () {
      var workspace = document.querySelector("[data-recruiting-workspace]");
      if (!workspace) return;
      var filters = Array.prototype.slice.call(workspace.querySelectorAll("[data-recruiting-filter]"));
      var cards = Array.prototype.slice.call(workspace.querySelectorAll("[data-recruiting-status]"));
      var buttons = Array.prototype.slice.call(workspace.querySelectorAll("button[data-recruit-title]"));
      var title = workspace.querySelector("[data-recruit-title]:not(button)");
      var status = workspace.querySelector("[data-recruit-status-label]:not(button)");
      var body = workspace.querySelector("[data-recruit-body]:not(button)");
      var fields = workspace.querySelector("[data-recruit-fields]");
      var route = workspace.querySelector("[data-recruit-route]");

      filters.forEach(function (filter) {
        filter.addEventListener("click", function () {
          var value = filter.dataset.recruitingFilter;
          filters.forEach(function (item) { item.classList.remove("is-active"); });
          filter.classList.add("is-active");
          cards.forEach(function (card) {
            var show = value === "all" || card.dataset.recruitingStatus === value;
            card.hidden = !show;
          });
        });
      });

      buttons.forEach(function (button) {
        button.addEventListener("click", function () {
          title.textContent = button.dataset.recruitTitle || "";
          status.textContent = button.dataset.recruitStatusLabel || "";
          body.textContent = button.dataset.recruitBody || "";
          fields.textContent = button.dataset.recruitFields || "";
          route.textContent = button.dataset.recruitRoute || "";
        });
      });
    }());
